mapper.select:
SELECT A.VDATE startDate, A.MDATE endDate, ( SELECT MIN(C.VDATE) FROM FIN_CASH_PLAN C WHERE C.CASH_ID = B.CASH_ID ) firstPayDate, A.ISSUE_PRICE issuePrice, A.COUPON_SPECIES bondsType, E.BASIS basis, A.REGIST_ORG registOrg, F.INT_TYPE intRateType, G.PAY_CYCLE yearIntRate, G.CALC_RULE calMethod, H.EXERCISE_DATE nextExeDate, H.EXERCISE_PRICE nextExercisePrice, J.FACE_VALUE faceValue, nvl(F.RATE,E.YIELD) paperir FROM FIN_PRODUCT A LEFT JOIN FIN_CASH_INFO B ON A.FINPROD_ID = B.FINPROD_ID AND B.FINPROD_TYPE = #{finprodType} AND B.CASH_TYPE_1 = #{cashType1} LEFT JOIN FIN_PRODUCT_TYPE D ON D.FINPROD_ID = A.FINPROD_ID LEFT JOIN FIN_CASH_CALC_RULE E ON E.FINPROD_ID = A.FINPROD_ID AND E.FINPROD_TYPE2 = #{finprodType2} and E.IS_INITIAL = #{YES_NO_Y} LEFT JOIN FIN_RATE_INFO F ON F.CASH_ID = B.CASH_ID AND F.FINPROD_TYPE2 = #{finprodType2} LEFT JOIN FIN_CASH_PAY_RULE G ON G.CASH_ID = B.CASH_ID AND G.FINPROD_TYPE2 = #{finprodType2} LEFT JOIN ( SELECT * FROM FIN_EXERCISE_PLAN WHERE EXERCISE_DATE IN ( SELECT MIN(EXERCISE_DATE) FROM FIN_EXERCISE_PLAN WHERE FINPROD_ID = #{finprodId}
AND EXERCISE_DATE >= #{sysDate} ) AND FINPROD_ID = #{finprodId}
) H ON 1=1 LEFT JOIN FIN_PRODUCT_ADD J on A.FINPROD_ID = J.FINPROD_ID WHERE A.FINPROD_ID = #{finprodId}

SELECT
       100 - NVL(sum(fcp.PRIN_AMT), 0)
FROM
     FIN_CASH_PLAN fcp
     inner join FIN_CASH_INFO fci
     on fcp.CASH_ID = fci.CASH_ID
WHERE
    fcp.FINPROD_ID = #{finprodId}
    AND fcp.MDATE < #{settleDate}
    and fci.CASH_TYPE_1 = #{cashType1}
